sql.where:
t.deleted = 0

    AND t.version_id = #{req.versionId}


    AND t.task_no LIKE CONCAT('%', #{req.taskNo}, '%')


    AND t.prod_order_no LIKE CONCAT('%', #{req.prodOrderNo}, '%')


    AND t.op_code = #{req.opCode}


    AND t.plant_id = #{req.plantId}


    AND t.workshop_id = #{req.workshopId}


    AND t.project_id = #{req.projectId}


    AND t.res_id = #{req.resId}


    AND t.locked_flag = #{req.lockedFlag}


    AND t.status = #{req.status}


    AND t.start_time BETWEEN #{req.startTime[0]} AND #{req.startTime[1]}


    AND t.end_time BETWEEN #{req.endTime[0]} AND #{req.endTime[1]}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
